def mob(i):
    rg = random.Random(1000 + i * 7919); t = rg.random()
    kind = 'fam' if t < 0.6 else 'vol' if t < 0.9 else 'oth'
    st = rg.choices(['hs', 'uni', 'work'], [0.2, 0.25, 0.55])[0]; how = rg.choice(HOW[kind])
    if st == 'hs': s = rg.choice(HS); bg = f'{s}を出てすぐ、{how}'; sc = f'{s}です'
    elif st == 'uni': u, f = rg.choice(UNI); bg = f'{u}の{f}にいたときに、{how}'; sc = f'{u}の{f}です'
    else: u, f = rg.choice(UNI); c, j = rg.choice(JOB); bg = f'{u}を出て、{c}で{j}をしていました。{how}'; sc = f'{u}の{f}です'
    rel = 'none' if kind == 'oth' else ('close' if rg.random() < 0.15 else 'dist') if kind == 'fam' else ('none' if rg.random() < 0.4 else 'dist')
    return {'bg': bg, 'sc': sc, 'sk': rg.choice(SKILL), 'rel': rg.choice(REL[rel]), 'kind': kind, 'relk': rel, 'v': (rg.randint(-8, 8), rg.randint(-8, 10))}
NMOB = 140
async def one(t, p, v, r, pi):
    for a in range(4):
        try: await edge_tts.Communicate(t, v, rate=f'{r:+d}%', pitch=f'{pi:+d}Hz').save(p); return
        except Exception: await asyncio.sleep(2 * (a + 1))
async def main():
    os.makedirs(D, exist_ok=True); sem = asyncio.Semaphore(8); jobs = []; out = {'named': {}, 'mob': []}
    def put(name, txt, prof):
        p = os.path.join(D, name + '.mp3')
        if not os.path.exists(p) or os.path.getsize(p) < 500:
            async def go(): 
                async with sem: await one(txt.replace('…', '、'), p, *prof)
            jobs.append(go())
        return {'text': txt, 'file': 'cvbg/' + name + '.mp3'}
    for k, (bg, sc, sk, rel) in NAMED.items():
        pr = PROFILES.get(k, (N, 0, 0)); out['named'][k] = {f: put(f'{k}_{f}', t, pr) for f, t in (('bg', bg), ('sc', sc), ('sk', '特技は、' + sk if not sk.startswith('特技') else sk), ('rel', rel))}
    for i in range(NMOB):
        m = mob(i); pr = (N, *m['v']); o = {f: put(f'm{i}_{f}', t, pr) for f, t in (('bg', m['bg']), ('sc', m['sc']), ('sk', '特技は、' + m['sk']), ('rel', m['rel']))}; o['kind'] = m['kind']; o['relk'] = m['relk']; out['mob'].append(o)
    await asyncio.gather(*jobs)
    open(os.path.join(ROOT, 'assets', 'voices', 'voices_cvbg.js'), 'w').write('// 自動生成 (tools/add_cvbg_voices.py)。幕四の身の上話\nwindow.VOICE_CVBG = ' + json.dumps(out, ensure_ascii=False) + ';\n')
    from collections import Counter; print(len(jobs), Counter(o['kind'] for o in out['mob']), Counter(o['relk'] for o in out['mob']))
asyncio.run(main())
